      "path": "scripts/install.sh",
      "content": "#!/usr/bin/env bash\n# 把皮肤装进一份 deepseek-harness 源码检出。\n# 用法：scripts/install.sh /path/to/deepseek-harness\nset -euo pipefail\n\nHERE=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")/..\" && pwd)\"\nTARGET=\"${1:-}\"\n# 宿主补丁相对这一版 DSH 源码生成；版本对不上就拒绝，避免装出一半。\nBASELINE=\"0.1.0-rc.7\"\n\ndie() { printf '\\033[31m✗ %s\\033[0m\\n' \"$*\" >&2; exit 1; }\nok()  { printf '\\033[32m✓ %s\\033[0m\\n' \"$*\"; }\nsay() { printf '  %s\\n' \"$*\"; }\n\n[ -n \"$TARGET\" ] || die \"用法：$0 /path/to/deepseek-harness\"\n[ -d \"$TARGET\" ] || die \"目录不存在：$TARGET\"\nTARGET=\"$(cd \"$TARGET\" && pwd)\"\n\ngrep -q '\"@deepseek-ai/dsh-root\"' \"$TARGET/package.json\" 2>/dev/null \\\n  || die \"这不像是 deepseek-harness 源码检出：$TARGET\"\n\n[ -d \"$TARGET/packages/client/ui-theme\" ] \\\n  || die \"找不到 packages/client/ui-theme，仓库结构对不上\"\n\nHOST_VER=\"$(node -p \"JSON.parse(require('fs').readFileSync(process.argv[1],'utf8')).version\" \"$TARGET/package.json\")\"\n[ \"$HOST_VER\" = \"$BASELINE\" ] \\\n  || die \"本包基于 DSH ${BASELINE}，目标是 ${HOST_VER}。请换一份匹配的源码，或更新 patches/host-integration.patch\"\n\nprintf '\\n\\033[1mDeepSeek Harness Skin 安装（DSH %s）\\033[0m\\n' \"$BASELINE\"\nsay \"目标仓库：$TARGET\"\n\n# 1. 备份要覆盖的文件，装错了能原样退回。\n#    已经装过皮肤就跳过，否则备份的是「装过之后」的样子，卸载会退不干净。\nif [ -f \"$TARGET/packages/client/ui-theme/src/skin-version.ts\" ]; then\n  ok \"目标已装过皮肤，跳过备份（首次安装的备份仍在 $HOME/.dsh-skin-backups/）\"\nelse\n  STAMP=\"$(date +%Y%m%d-%H%M%S)\"\n  BACKUP=\"$HOME/.dsh-skin-backups/$STAMP\"\n  mkdir -p \"$BACKUP/packages/client\"\n  cp -R \"$TARGET/packages/client/ui-theme\" \"$BACKUP/packages/client/ui-theme\"\n  while IFS= read -r rel; do\n    mkdir -p \"$BACKUP/$(dirname \"$rel\")\"\n    cp \"$TARGET/$rel\" \"$BACKUP/$rel\"\n  done < \"$HERE/scripts/patched-files.txt\"\n  printf '%s\\n' \"$TARGET\" > \"$BACKUP/.target\"\n  ok \"已备份到 $BACKUP\"\nfi\n\n# 2. 覆盖 ui-theme 包（Windows Git Bash 往往没有 rsync）\ncopy_theme() {\n  local src=\"$1\" dest=\"$2\"\n  mkdir -p \"$dest\"\n  if command -v rsync >/dev/null 2>&1; then\n    rsync -a --exclude 'node_modules' --exclude 'dist' --exclude 'lib' \"$src/\" \"$dest/\"\n    return\n  fi\n  (cd \"$src\" && tar -cf - --exclude=node_modules --exclude=dist --exclude=lib .) \\\n    | (cd \"$dest\" && tar -xf -)\n}\n\ncopy_theme \"$HERE/tree/packages/client/ui-theme\" \"$TARGET/packages/client/ui-theme\"\nnode \"$HERE/scripts/pin-theme-version.mjs\" \"$TARGET/packages/client/ui-theme/package.json\" \"$HOST_VER\"\nok \"已写入 ui-theme 皮肤包（壁纸目录 + 自定义皮肤 + 更新检查）\"\n\n# 3. 打宿主集成补丁（背景层、标题栏挂钩、消息气泡、皮肤 CSS 入口）\ncd \"$TARGET\"\nPATCH=\"$HERE/patches/host-integration.patch\"\nif git -C \"$TARGET\" rev-parse --git-dir >/dev/null 2>&1; then\n  if git apply --check \"$PATCH\" 2>/dev/null; then\n    git apply \"$PATCH\"\n    ok \"已打宿主集成补丁\"\n  elif git apply --check --reverse \"$PATCH\" 2>/dev/null; then\n    ok \"宿主集成补丁已在，跳过\"\n  else\n    die \"补丁打不上。你的 deepseek-harness 版本可能和本皮肤包不匹配（本包基于 ${BASELINE}），请手工比对 patches/host-integration.patch\"\n  fi\nelse\n  patch -p1 --forward --silent < \"$PATCH\" \\\n    || die \"补丁打不上，请手工比对 patches/host-integration.patch\"\n  ok \"已打宿主集成补丁\"\nfi\n\nprintf '\\n\\033[1m接下来手动跑这三条\\033[0m\\n'\nsay \"cd $TARGET\"\nsay \"pnpm install\"\nsay \"pnpm run build\"\nsay \"pnpm dsh web\"\nprintf '\\n浏览器打开 http://127.0.0.1:3080 ，左下角「设置」→「皮肤」就能换。\\n'\nprintf '想退回原样：scripts/uninstall.sh %s\\n\\n' \"$TARGET\"\n"
